# -*- coding: utf-8 -*-
"""प्रश्न और मुण्डक उपनिषद — अर्थ (अपने शब्दों में, सीधा शब्दार्थ)।

प्रश्न: कुंजी "प्रश्न.मंत्र"। मुण्डक: कुंजी "खंड-क्रम.मंत्र" — 1 = १.१, 2 = १.२, 3 = २.१,
4 = २.२, 5 = ३.१, 6 = ३.२।
"""

PRASHNA = {
    '1.1': 'सुकेशा भारद्वाज, शैब्य सत्यकाम, सौर्यायणी गार्ग्य, कौसल्य आश्वलायन, भार्गव वैदर्भि और कबंधी कात्यायन — ये छहों ब्रह्म में लगे हुए, ब्रह्म में निष्ठा रखने वाले और परब्रह्म की खोज करने वाले थे। यह सोचकर कि ये हमें वह सब बता देंगे, वे हाथ में समिधा लेकर भगवान पिप्पलाद के पास पहुँचे।',
    '1.2': 'उन ऋषि ने उनसे कहा — "तप, ब्रह्मचर्य और श्रद्धा के साथ एक बरस और यहाँ रहो; फिर जो चाहो वह प्रश्न पूछना। अगर हम जानते होंगे तो तुम्हें सब बता देंगे।"',
    '1.3': 'एक बरस बाद कबंधी कात्यायन ने पास आकर पूछा — "भगवन्, ये सारे प्राणी कहाँ से पैदा होते हैं?"',
    '1.4': 'पिप्पलाद ने कहा — "प्रजापति को प्रजा की इच्छा हुई। उन्होंने तप किया, और तप करके एक जोड़ा पैदा किया — रयि (अन्न, पदार्थ) और प्राण (जीवन-शक्ति) — यह सोचकर कि ये दोनों मेरे लिए तरह-तरह की प्रजा बनाएँगे।"',
    '1.5': '"सूर्य ही प्राण है और चंद्रमा ही रयि है। जो कुछ आकार वाला है और जो बिना आकार का है — यह सब रयि ही है; इसलिए आकार ही रयि है।"',
    '1.6': '"सूर्य उगकर जब पूरब दिशा में प्रवेश करता है, तो पूरब के प्राणों को अपनी किरणों में ले लेता है। और जब वह दक्षिण, पश्चिम, उत्तर, नीचे, ऊपर और बीच की दिशाओं को — सबको प्रकाशित करता है, तो सारे प्राणों को अपनी किरणों में ले लेता है।"',
    '1.7': '"वही यह वैश्वानर, सब रूपों वाला, प्राण और अग्नि बनकर उगता है। यही बात इस ऋचा में कही गई है —"',
    '1.8': '"ज्ञानी उसे जानते हैं जो सब रूपों वाला, किरणों वाला, सब कुछ जानने वाला, सबका आश्रय, अकेली ज्योति और तपने वाला है। हज़ार किरणों वाला, सैकड़ों रूपों में रहने वाला, प्राणियों का प्राण — यह सूर्य उग रहा है।"',
    '1.9': '"बरस ही प्रजापति है। उसके दो मार्ग हैं — दक्षिण और उत्तर। जो यज्ञ और परोपकार के कामों को ही सब कुछ मानकर करते हैं, वे चंद्रलोक को ही जीतते हैं, और वे ही फिर लौटकर आते हैं। इसलिए संतान चाहने वाले ऋषि दक्षिण का मार्ग लेते हैं। यह पितरों का मार्ग ही रयि है।"',
    '1.10': '"और जो तप, ब्रह्मचर्य, श्रद्धा और विद्या से आत्मा को खोजते हैं, वे उत्तर के मार्ग से सूर्य को जीतते हैं। वही प्राणों का घर है, वही अमृत है, वही निर्भय है, वही परम आश्रय है; वहाँ से कोई लौटता नहीं। वही रुकने की जगह है। इस पर यह श्लोक है —"',
    '1.11': '"कोई उसे पाँच पैरों और बारह रूपों वाला पिता कहते हैं, जो आकाश के ऊपरी आधे में जल से भरा बैठा है। और दूसरे कहते हैं कि वह सब देखने वाला, सात पहियों और छह अरों वाले रथ में बैठा है।"',
    '1.12': '"महीना ही प्रजापति है। उसका कृष्ण पक्ष रयि है और शुक्ल पक्ष प्राण। इसलिए ये ऋषि शुक्ल पक्ष में यज्ञ करते हैं, और दूसरे लोग दूसरे पक्ष में।"',
    '1.13': '"दिन और रात ही प्रजापति हैं। दिन ही प्राण है और रात ही रयि। जो दिन में रति करते हैं, वे अपने प्राण को ही गँवाते हैं; और जो रात में रति करते हैं, वह ब्रह्मचर्य ही है।"',
    '1.14': '"अन्न ही प्रजापति है। उसी से वीर्य बनता है, और उसी से ये सारे प्राणी पैदा होते हैं।"',
    '1.15': '"जो प्रजापति के इस व्रत का पालन करते हैं, वे संतान का जोड़ा पैदा करते हैं। और ब्रह्मलोक उन्हीं का है जिनमें तप और ब्रह्मचर्य है, और जिनमें सत्य टिका हुआ है।"',
    '1.16': '"वह निर्मल ब्रह्मलोक उन्हीं का है जिनमें न कुटिलता है, न झूठ, और न छल।"',

    '2.1': 'फिर भार्गव वैदर्भि ने पूछा — "भगवन्, कितने देवता प्राणी के शरीर को सँभाले रखते हैं? उनमें से कौन इसे प्रकाशित करते हैं? और उनमें सबसे बड़ा कौन है?"',
    '2.2': 'पिप्पलाद ने कहा — "वह देवता आकाश है; और वायु, अग्नि, जल, पृथ्वी, वाणी, मन, आँख और कान भी। वे अपनी महिमा दिखाकर कहने लगे — इस शरीर को थामकर हम ही सँभाले हुए हैं।"',
    '2.3': '"उनसे सबसे बड़े प्राण ने कहा — भ्रम में मत पड़ो। मैं ही अपने को पाँच भागों में बाँटकर इस शरीर को थामे और सँभाले हुए हूँ। पर उन्होंने उसकी बात पर भरोसा नहीं किया।"',
    '2.4': '"तब प्राण स्वाभिमान से मानो शरीर से ऊपर निकलने लगा। उसके निकलते ही बाक़ी सब भी निकलने लगे, और उसके ठहरते ही सब ठहर गए। जैसे रानी मक्खी के उड़ने पर सारी मधुमक्खियाँ उड़ जाती हैं और उसके बैठने पर सब बैठ जाती हैं — वैसा ही वाणी, मन, आँख और कान का हुआ। तब वे प्रसन्न होकर प्राण की स्तुति करने लगे —"',
    '2.5': '"यही अग्नि बनकर तपता है, यही सूर्य है, यही बादल है, यही इंद्र है, यही वायु है, यही पृथ्वी है; यही रयि है, यही देव है — जो है और जो नहीं है, और जो अमृत है, वह सब यही है।"',
    '2.6': '"जैसे रथ की नाभि में अरे लगे रहते हैं, वैसे ही प्राण में सब कुछ टिका है — ऋचाएँ, यजु, साम, यज्ञ, क्षत्रिय और ब्राह्मण।"',
    '2.7': '"हे प्राण, तुम ही प्रजापति होकर गर्भ में चलते हो, और तुम ही जन्म लेते हो। ये सारे प्राणी तुम्हें ही भेंट चढ़ाते हैं — तुम, जो इंद्रियों के साथ शरीर में रहते हो।"',
    '2.8': '"तुम देवताओं तक हवि पहुँचाने वालों में सबसे श्रेष्ठ हो; पितरों की पहली स्वधा तुम हो; और अथर्वा-अंगिरा ऋषियों का सच्चा आचरण भी तुम ही हो।"',
    '2.9': '"हे प्राण, तेज से तुम इंद्र हो; रक्षा करने वाले रुद्र तुम हो; तुम ही अंतरिक्ष में चलने वाले सूर्य हो — ज्योतियों के स्वामी।"',
    '2.10': '"हे प्राण, जब तुम वर्षा बनकर बरसते हो, तब तुम्हारी यह प्रजा आनंद से भर जाती है — कि अब मनचाहा अन्न होगा।"',
    '2.11': '"हे प्राण, तुम व्रात्य हो — जन्म से ही शुद्ध, जिसे किसी संस्कार की ज़रूरत नहीं; तुम एकर्षि अग्नि हो, सब कुछ खाने वाले और जगत के सच्चे स्वामी। हम तुम्हें भोजन देने वाले हैं; हे वायु, तुम हमारे पिता हो।"',
    '2.12': '"तुम्हारा जो रूप वाणी में बसा है, जो कान में और जो आँख में है, और जो मन में फैला है — उसे कल्याणकारी बनाओ; हमें छोड़कर मत जाओ।"',
    '2.13': '"तीनों लोकों में जो कुछ टिका है, वह सब प्राण के वश में है। जैसे माँ बेटों की रक्षा करती है, वैसे हमारी रक्षा करो; हमें श्री और बुद्धि दो।"',

    '3.1': 'फिर कौसल्य आश्वलायन ने पूछा — "भगवन्, यह प्राण कहाँ से पैदा होता है? इस शरीर में कैसे आता है? अपने को बाँटकर कैसे रहता है? किस रास्ते निकलता है? बाहर के जगत को और भीतर के शरीर को कैसे सँभालता है?"',
    '3.2': 'पिप्पलाद ने कहा — "तुम बहुत कठिन प्रश्न पूछ रहे हो। पर तुम ब्रह्म में बहुत निष्ठा रखते हो, इसलिए मैं तुम्हें बताता हूँ।"',
    '3.3': '"यह प्राण आत्मा से पैदा होता है। जैसे मनुष्य के साथ उसकी छाया रहती है, वैसे ही यह आत्मा में फैला है; और मन के किए हुए — संकल्प और कर्म — से इस शरीर में आता है।"',
    '3.4': '"जैसे सम्राट अपने अधिकारियों को काम सौंपता है — तुम इन गाँवों को सँभालो, तुम इन गाँवों को — वैसे ही यह प्राण दूसरे प्राणों को अलग-अलग जगह लगा देता है।"',
    '3.5': '"मल-मूत्र के अंगों में वह अपान को रखता है; आँख और कान में, मुँह और नाक के रास्ते, प्राण स्वयं रहता है; और बीच में समान। यही खाए हुए अन्न को सब जगह बराबर पहुँचाता है; उसी से ये सात लपटें उठती हैं।"',
    '3.6': '"यह आत्मा हृदय में है। यहाँ एक सौ एक नाड़ियाँ हैं; उनमें से हर एक की सौ-सौ शाखाएँ हैं, और हर शाखा की बहत्तर-बहत्तर हज़ार उपशाखाएँ। इन सबमें व्यान चलता है।"',
    '3.7': '"और उनमें से एक नाड़ी से ऊपर की ओर उदान चलता है। वह पुण्य से पुण्य-लोक में ले जाता है, पाप से पाप-लोक में, और दोनों से मनुष्य-लोक में।"',
    '3.8': '"सूर्य ही बाहर का प्राण है; वह उगकर आँख में रहने वाले प्राण पर कृपा करता है। पृथ्वी में जो देवता है, वह मनुष्य के अपान को थामे रहती है। बीच में जो आकाश है, वह समान है; और वायु व्यान है।"',
    '3.9': '"तेज ही उदान है। इसलिए जिसका तेज बुझ जाता है, वह मन में लीन हुई इंद्रियों के साथ दूसरे जन्म में जाता है।"',
    '3.10': '"मरते समय मनुष्य का चित्त जैसा होता है, उसी के साथ वह प्राण में आता है। प्राण तेज से जुड़कर, आत्मा के साथ, उसे उसके संकल्प के अनुसार लोक में ले जाता है।"',
    '3.11': '"जो विद्वान प्राण को इस तरह जानता है, उसकी संतान की परंपरा नहीं टूटती और वह अमर हो जाता है। इस पर यह श्लोक है —"',
    '3.12': '"प्राण की उत्पत्ति, उसका आना, उसका स्थान, पाँच रूपों में उसका फैलाव और शरीर के भीतर उसका रहना — यह जानकर मनुष्य अमरता पाता है; यह जानकर अमरता पाता है।"',

    '4.1': 'फिर सौर्यायणी गार्ग्य ने पूछा — "भगवन्, इस मनुष्य में कौन सोते हैं, और कौन जागते रहते हैं? वह कौन देव है जो सपने देखता है? यह सुख किसे होता है? और सब किसमें जाकर टिकते हैं?"',
    '4.2': 'पिप्पलाद ने कहा — "गार्ग्य, जैसे डूबते सूरज की सारी किरणें उसके तेज के गोले में एक हो जाती हैं, और उसके फिर उगने पर फिर फैल जाती हैं — वैसे ही सारी इंद्रियाँ सबसे ऊँचे देव, मन, में एक हो जाती हैं। इसीलिए तब यह मनुष्य न सुनता है, न देखता है, न सूँघता है, न चखता है, न छूता है, न बोलता है, न पकड़ता है, न आनंद लेता है, न मल त्यागता है, न चलता है। तब कहते हैं कि वह सो रहा है।"',
    '4.3': '"शरीर रूपी इस नगर में प्राण की अग्नियाँ ही जागती रहती हैं। यह अपान गार्हपत्य अग्नि है; व्यान दक्षिण अग्नि (अन्वाहार्यपचन) है; और प्राण आहवनीय अग्नि है — क्योंकि वह गार्हपत्य से ही ले जाई जाती है।"',
    '4.4': '"साँस का लेना और छोड़ना दो आहुतियाँ हैं; जो इन्हें बराबर पहुँचाता है वह समान है। मन ही यजमान है। यज्ञ का चाहा हुआ फल ही उदान है; वही इस यजमान को हर रोज़ गहरी नींद में ब्रह्म के पास ले जाता है।"',
    '4.5': '"यहीं सपने में यह देव — मन — अपनी महिमा का अनुभव करता है। जो देखा था उसे फिर देखता है, जो सुना था उसे फिर सुनता है; अलग-अलग देशों और दिशाओं में जो अनुभव किया था उसे बार-बार अनुभव करता है। देखा और अनदेखा, सुना और अनसुना, अनुभव किया और न किया हुआ, जो है और जो नहीं है — वह सब देखता है; ख़ुद सब कुछ बनकर देखता है।"',
    '4.6': '"जब वह तेज से ढक जाता है, तब वह देव सपने नहीं देखता। तब इस शरीर में वह गहरी नींद का सुख होता है।"',
    '4.7': '"हे सोम्य, जैसे पक्षी अपने बसेरे के पेड़ पर आकर टिक जाते हैं, वैसे ही वह सब कुछ परम आत्मा में जाकर टिक जाता है —"',
    '4.8': '"पृथ्वी और उसका सूक्ष्म रूप, जल और उसका सूक्ष्म रूप, तेज और उसका सूक्ष्म रूप, वायु और उसका सूक्ष्म रूप, आकाश और उसका सूक्ष्म रूप; आँख और जो देखा जाता है, कान और जो सुना जाता है, नाक और जो सूँघा जाता है, जीभ और जो चखा जाता है, त्वचा और जो छुआ जाता है; वाणी और जो बोला जाता है, हाथ और जो पकड़ा जाता है, जननेंद्रिय और उसका सुख, गुदा और जो त्यागा जाता है, पैर और जो चला जाता है; मन और जो सोचा जाता है, बुद्धि और जो समझा जाता है, अहंकार और उसका विषय, चित्त और जो चेता जाता है, तेज और जो प्रकाशित होता है, प्राण और जो उससे सँभला है।"',
    '4.9': '"यही देखने वाला, छूने वाला, सुनने वाला, सूँघने वाला, चखने वाला, सोचने वाला, समझने वाला और करने वाला है — विज्ञान-रूप आत्मा, पुरुष। वह परम अविनाशी आत्मा में जाकर टिक जाता है।"',
    '4.10': '"हे सोम्य, जो उस बिना छाया के, बिना शरीर के, बिना रंग के, शुद्ध और अविनाशी को जान लेता है, वह परम अविनाशी को ही पा लेता है। वह सब कुछ जानने वाला और सब कुछ हो जाता है। इस पर यह श्लोक है —"',
    '4.11': '"हे सोम्य, विज्ञान-रूप आत्मा, सारे देवताओं (इंद्रियों) के साथ, और प्राण और पाँचों भूत जिसमें जाकर टिकते हैं — उस अविनाशी को जो जान लेता है, वह सब कुछ जानने वाला होकर सबमें समा जाता है।"',

    '5.1': 'फिर शैब्य सत्यकाम ने पूछा — "भगवन्, मनुष्यों में जो कोई मरते दम तक ओंकार का ध्यान करता रहे, वह उससे कौन सा लोक जीतता है?" पिप्पलाद ने कहा —',
    '5.2': '"सत्यकाम, यह जो ओंकार है, यही पर और अपर — दोनों ब्रह्म है। इसलिए जानने वाला इसी के सहारे दोनों में से किसी एक को पा लेता है।"',
    '5.3': '"अगर वह एक मात्रा का ध्यान करता है, तो उसी से ज्ञान पाकर जल्दी ही पृथ्वी पर लौट आता है। ऋचाएँ उसे मनुष्य-लोक में ले आती हैं; वहाँ वह तप, ब्रह्मचर्य और श्रद्धा से युक्त होकर महिमा का अनुभव करता है।"',
    '5.4': '"अगर वह दो मात्राओं से मन में ध्यान करता है, तो यजु-मंत्र उसे अंतरिक्ष में, चंद्रलोक तक ले जाते हैं। चंद्रलोक का ऐश्वर्य भोगकर वह फिर लौट आता है।"',
    '5.5': '"पर जो तीनों मात्राओं वाले इसी ॐ अक्षर से परम पुरुष का ध्यान करता है, वह तेज-रूप सूर्य में पहुँचता है। जैसे साँप केंचुली से छूट जाता है, वैसे ही वह पाप से छूट जाता है। साम-मंत्र उसे ब्रह्मलोक में ले जाते हैं; और वहाँ वह इस जीव-समूह से परे, सबसे परे, शरीर-रूपी नगर में रहने वाले पुरुष को देखता है। इस पर ये दो श्लोक हैं —"',
    '5.6': '"तीनों मात्राएँ अलग-अलग बरती जाएँ तो मृत्यु के घेरे में ही रहती हैं। पर जब वे एक-दूसरे से जुड़ी हों, अलग न हों, और बाहर, भीतर और बीच की क्रियाओं में ठीक से लगाई जाएँ — तब जानने वाला डगमगाता नहीं।"',
    '5.7': '"ऋचाओं से यह लोक मिलता है, यजु से अंतरिक्ष, और साम से वह लोक जिसे ज्ञानी जानते हैं। और ओंकार के ही सहारे विद्वान उसे भी पा लेता है जो शांत, अजर, अमर, निर्भय और परम है।"',

    '6.1': 'फिर सुकेशा भारद्वाज ने पूछा — "भगवन्, कोसल के राजकुमार हिरण्यनाभ ने मेरे पास आकर पूछा था कि भारद्वाज, क्या तुम सोलह कलाओं वाले पुरुष को जानते हो? मैंने उस कुमार से कहा — मैं उसे नहीं जानता; जानता होता तो तुम्हें क्यों न बताता? जो झूठ बोलता है वह जड़ से सूख जाता है, इसलिए मैं झूठ नहीं बोल सकता। वह चुपचाप रथ पर चढ़कर चला गया। वही मैं आपसे पूछता हूँ — वह पुरुष कहाँ है?"',
    '6.2': 'पिप्पलाद ने कहा — "हे सोम्य, वह पुरुष यहीं, इस शरीर के भीतर है — जिसमें ये सोलह कलाएँ पैदा होती हैं।"',
    '6.3': '"उस पुरुष ने सोचा — किसके निकल जाने पर मैं निकल जाऊँगा, और किसके टिके रहने पर टिका रहूँगा?"',
    '6.4': '"उसने प्राण को रचा; प्राण से श्रद्धा, आकाश, वायु, तेज, जल, पृथ्वी, इंद्रियाँ और मन; फिर अन्न, अन्न से बल, तप, मंत्र, कर्म, लोक, और लोकों में नाम।"',
    '6.5': '"जैसे समुद्र की ओर बहती ये नदियाँ समुद्र में पहुँचकर लीन हो जाती हैं, उनके नाम और रूप मिट जाते हैं, और सब समुद्र ही कहलाता है — वैसे ही इस देखने वाले की ये सोलह कलाएँ, जिनका लक्ष्य पुरुष है, पुरुष में पहुँचकर लीन हो जाती हैं; उनके नाम और रूप मिट जाते हैं, और सब पुरुष ही कहलाता है। तब वह कलाओं से रहित और अमर हो जाता है। इस पर यह श्लोक है —"',
    '6.6': '"जैसे रथ की नाभि में अरे लगे रहते हैं, वैसे ही जिसमें सब कलाएँ टिकी हैं — उस जानने योग्य पुरुष को जानो, ताकि मृत्यु तुम्हें दुख न दे।"',
    '6.7': 'पिप्पलाद ने उनसे कहा — "मैं इस परब्रह्म को इतना ही जानता हूँ। इससे परे कुछ नहीं है।"',
    '6.8': 'उन्होंने उनकी पूजा करते हुए कहा — "आप ही हमारे पिता हैं, जो हमें अविद्या के पार, दूसरे किनारे पर पहुँचा रहे हैं।" परम ऋषियों को नमस्कार! परम ऋषियों को नमस्कार!',
}

_NA_TATRA = '"वहाँ न सूर्य चमकता है, न चाँद-तारे; न ये बिजलियाँ चमकती हैं — फिर यह आग तो क्या। उसी के चमकने से सब चमकते हैं; उसी के प्रकाश से यह सब प्रकाशित है।"'

MUNDAKA = {
    # ── पहला मुण्डक, पहला खंड ───────────────────────────────────────────────
    '1.1': 'ब्रह्मा देवताओं में सबसे पहले प्रकट हुए — सारे जगत को रचने वाले और उसकी रक्षा करने वाले। उन्होंने सब विद्याओं की आधार ब्रह्मविद्या अपने बड़े पुत्र अथर्वा को बताई।',
    '1.2': 'ब्रह्मा ने जो विद्या अथर्वा को बताई थी, वही ब्रह्मविद्या अथर्वा ने पुराने समय में अंगिर को बताई। अंगिर ने उसे भरद्वाज-गोत्र के सत्यवह को बताया, और भारद्वाज ने परंपरा से चली आई वह विद्या अंगिरा को बताई।',
    '1.3': 'बड़े गृहस्थ शौनक विधि के साथ अंगिरा के पास पहुँचे और पूछा — "भगवन्, वह क्या है जिसे जान लेने पर यह सब कुछ जान लिया जाता है?"',
    '1.4': 'अंगिरा ने उनसे कहा — "ब्रह्म को जानने वाले कहते हैं कि दो विद्याएँ जानने योग्य हैं — परा और अपरा।"',
    '1.5': '"उनमें अपरा है — ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद, शिक्षा, कल्प, व्याकरण, निरुक्त, छंद और ज्योतिष। और परा वह है जिससे वह अविनाशी जाना जाता है।"',
    '1.6': '"वह जो न देखा जा सकता है, न पकड़ा जा सकता है; जिसका न कोई गोत्र है, न वर्ण; जिसके न आँख-कान हैं, न हाथ-पैर; जो नित्य है, सब जगह फैला है, सबमें पहुँचा हुआ और बहुत सूक्ष्म है — उस अविनाशी को, जो सब प्राणियों का मूल कारण है, धीर पुरुष सब ओर देखते हैं।"',
    '1.7': '"जैसे मकड़ी जाला निकालती है और फिर उसे अपने में समेट लेती है, जैसे पृथ्वी से पेड़-पौधे उगते हैं, जैसे जीवित मनुष्य के शरीर से बाल और रोएँ निकलते हैं — वैसे ही उस अविनाशी से यह सारा जगत पैदा होता है।"',
    '1.8': '"तप से ब्रह्म फैलता है; उससे अन्न पैदा होता है; अन्न से प्राण, मन, सत्य, लोक, और कर्मों में उनका अमर फल।"',
    '1.9': '"जो सब कुछ जानता है, सबको समझता है, जिसका तप ज्ञान ही है — उसी से यह ब्रह्म (हिरण्यगर्भ), नाम, रूप और अन्न पैदा होते हैं।"',

    # ── पहला मुण्डक, दूसरा खंड ──────────────────────────────────────────────
    '2.1': '"यह सत्य है — ऋषियों ने मंत्रों में जिन कर्मों को देखा, वे तीनों वेदों में बहुत तरह से फैले हुए हैं। सत्य की चाह रखने वालो, उन्हें नियम से करो; अच्छे कर्म के लोक तक पहुँचने का तुम्हारा यही रास्ता है।"',
    '2.2': '"जब अग्नि अच्छी तरह जल उठे और उसकी लपट लहराने लगे, तब घी की दो आहुतियों के बीच में बाक़ी आहुतियाँ डाले।"',
    '2.3': '"जिसका अग्निहोत्र अमावस्या और पूर्णिमा के यज्ञ के बिना, चातुर्मास्य के बिना, नए अन्न के यज्ञ के बिना और अतिथि-सत्कार के बिना है; जो समय पर नहीं हुआ, वैश्वदेव के बिना हुआ या विधि के विरुद्ध हुआ — वह उसके सातों लोकों को नष्ट कर देता है।"',
    '2.4': '"काली, कराली, मनोजवा, सुलोहिता, सुधूम्रवर्णा, स्फुलिंगिनी और देवी विश्वरुची — ये अग्नि की सात लहराती हुई जीभें (लपटें) हैं।"',
    '2.5': '"जो इन चमकती लपटों में ठीक समय पर आहुतियाँ देता हुआ कर्म करता है, उसे ये आहुतियाँ सूर्य की किरणें बनकर वहाँ ले जाती हैं जहाँ देवताओं का एक स्वामी रहता है।"',
    '2.6': '"वे चमकती हुई आहुतियाँ आओ, आओ कहती हुई उस यजमान को सूर्य की किरणों से ले जाती हैं; मीठे वचन बोलती और उसका आदर करती हुई कहती हैं — यह तुम्हारे अच्छे कर्मों से कमाया हुआ पवित्र ब्रह्मलोक है।"',
    '2.7': '"पर यज्ञ-रूपी ये नावें कमज़ोर हैं — जिनमें अठारह जनों (सोलह ऋत्विज, यजमान और उसकी पत्नी) पर टिका हुआ छोटा कर्म बताया गया है। जो मूढ़ इसी को परम कल्याण मानकर ख़ुश होते हैं, वे फिर बुढ़ापे और मृत्यु में ही पड़ते हैं।"',
    '2.8': '"जो अविद्या के भीतर रहते हुए भी अपने को समझदार और पंडित मानते हैं, वे मूढ़ चोट खाते हुए भटकते रहते हैं — जैसे अंधे के पीछे चलते हुए अंधे।"',
    '2.9': '"अविद्या में तरह-तरह से पड़े हुए वे नासमझ सोचते हैं कि हमने सब पा लिया। कर्म करने वाले आसक्ति के कारण सच्चाई नहीं जान पाते; इसलिए जब उनके पुण्य का लोक ख़त्म होता है, तो वे दुखी होकर नीचे गिरते हैं।"',
    '2.10': '"यज्ञ और परोपकार के कामों को ही सबसे बड़ा मानने वाले वे मूढ़ किसी और कल्याण को नहीं जानते। वे स्वर्ग की ऊँचाई पर अपने पुण्य का फल भोगकर फिर इसी लोक में, या इससे भी नीचे के लोक में आ जाते हैं।"',
    '2.11': '"पर जो शांत और विद्वान लोग वन में रहकर, भिक्षा पर जीते हुए, तप और श्रद्धा का सेवन करते हैं — वे निर्मल होकर सूर्य के द्वार से वहाँ जाते हैं जहाँ वह अमर, अविनाशी पुरुष है।"',
    '2.12': '"कर्मों से मिलने वाले लोकों को परखकर ब्राह्मण वैराग्य पाए — क्योंकि जो किया हुआ नहीं है, नित्य है, वह किए हुए कर्म से नहीं मिलता। उसे जानने के लिए वह हाथ में समिधा लेकर ऐसे गुरु के ही पास जाए जो वेद का जानने वाला और ब्रह्म में टिका हुआ हो।"',
    '2.13': '"विधि से पास आए उस शिष्य को — जिसका चित्त शांत है और जो संयम वाला है — वह विद्वान गुरु ब्रह्मविद्या ठीक-ठीक वैसी ही बताए, जिससे सत्य और अविनाशी पुरुष जाना जाता है।"',

    # ── दूसरा मुण्डक, पहला खंड ──────────────────────────────────────────────
    '3.1': '"यह सत्य है — जैसे अच्छी तरह जलती आग से उसी जैसी हज़ारों चिनगारियाँ निकलती हैं, हे सोम्य, वैसे ही उस अविनाशी से तरह-तरह के जीव पैदा होते हैं और उसी में लौट जाते हैं।"',
    '3.2': '"वह पुरुष दिव्य है, बिना आकार का; बाहर भी है और भीतर भी; अजन्मा है; बिना प्राण का, बिना मन का, शुद्ध; और जो अविनाशी (अव्यक्त) सबसे परे है, उससे भी परे।"',
    '3.3': '"उसी से प्राण, मन और सारी इंद्रियाँ पैदा होती हैं; आकाश, वायु, तेज, जल, और सबको धारण करने वाली पृथ्वी भी।"',
    '3.4': '"अग्नि (द्युलोक) उसका सिर है, चंद्र और सूर्य उसकी आँखें, दिशाएँ उसके कान, खुले हुए वेद उसकी वाणी, वायु उसका प्राण, सारा जगत उसका हृदय, और उसके पैरों से पृथ्वी हुई। वही सब प्राणियों का अंतरात्मा है।"',
    '3.5': '"उसी से वह अग्नि (द्युलोक) हुई जिसकी समिधा सूर्य है; चंद्रमा से बादल, बादल से पृथ्वी पर औषधियाँ; पुरुष स्त्री में बीज डालता है — इस तरह उस पुरुष से बहुत सी प्रजा पैदा हुई।"',
    '3.6': '"उसी से ऋचाएँ, साम, यजु, दीक्षा, सारे यज्ञ और क्रतु, दक्षिणाएँ, बरस, यजमान और वे लोक हुए जहाँ चंद्रमा पवित्र करता है और जहाँ सूर्य तपता है।"',
    '3.7': '"उसी से तरह-तरह के देवता पैदा हुए, साध्य, मनुष्य, पशु और पक्षी; प्राण और अपान, धान और जौ, तप, श्रद्धा, सत्य, ब्रह्मचर्य और विधि।"',
    '3.8': '"उसी से सात प्राण (इंद्रियाँ) पैदा होते हैं, सात लपटें, सात समिधाएँ, सात होम, और ये सात लोक जिनमें प्राण चलते हैं — जो हृदय की गुफा में सोते हैं, और सात-सात करके रखे गए हैं।"',
    '3.9': '"इसी से सारे समुद्र और पहाड़ हुए; इसी से हर तरह की नदियाँ बहती हैं; इसी से सारी औषधियाँ और रस हुए — जिसके सहारे यह अंतरात्मा पाँच भूतों के बीच टिका है।"',
    '3.10': '"यह सारा जगत — कर्म, तप, और परम अमृत ब्रह्म — पुरुष ही है। हे सोम्य, जो इसे हृदय की गुफा में रखा हुआ जान लेता है, वह यहीं अविद्या की गाँठ काट देता है।"',

    # ── दूसरा मुण्डक, दूसरा खंड ─────────────────────────────────────────────
    '4.1': '"वह प्रकट है, पास ही है, और हृदय की गुफा में चलने वाला कहलाता है; वह बड़ा आधार है। जो चलता है, साँस लेता है और पलक झपकाता है — वह सब उसी में टिका है। उसे जानो — जो है भी और नहीं भी, जो चाहने योग्य है, जो प्राणियों की समझ से परे और सबसे श्रेष्ठ है।"',
    '4.2': '"जो तेज वाला है, जो सूक्ष्म से भी सूक्ष्म है, जिसमें सारे लोक और उनमें रहने वाले टिके हैं — वही अविनाशी ब्रह्म है; वही प्राण है, वही वाणी और मन है; वही सत्य है, वही अमृत है। हे सोम्य, उसी को बेधना है — उसे बेधो।"',
    '4.3': '"उपनिषद का महान अस्त्र — धनुष — हाथ में लो; उस पर उपासना से पैना किया हुआ बाण चढ़ाओ; उसी में लगे हुए चित्त से धनुष खींचो, और हे सोम्य, उस अविनाशी को ही अपना निशाना जानो।"',
    '4.4': '"ॐ धनुष है, आत्मा बाण है, और ब्रह्म उसका निशाना कहा गया है। बिना चूके उसे बेधना चाहिए; और बाण की तरह उसी में समा जाना चाहिए।"',
    '4.5': '"जिसमें द्युलोक, पृथ्वी और अंतरिक्ष पिरोए हुए हैं, और मन भी सारे प्राणों के साथ — उसी एक आत्मा को जानो। बाक़ी बातें छोड़ दो; अमरता तक पहुँचने का यही पुल है।"',
    '4.6': '"जहाँ सब नाड़ियाँ वैसे ही जुड़ी हैं जैसे रथ की नाभि में अरे — उस हृदय के भीतर यह आत्मा तरह-तरह के रूप लेता हुआ चलता है। ॐ — इस तरह आत्मा का ध्यान करो। अँधेरे के पार, दूसरे किनारे जाने के लिए तुम्हारा कल्याण हो।"',
    '4.7': '"जो सब कुछ जानता है, सबको समझता है, और पृथ्वी पर जिसकी यह महिमा है — वह आत्मा ब्रह्म के दिव्य नगर में, हृदय के आकाश में टिका है। वह मन-रूप है, प्राण और शरीर को चलाने वाला है; हृदय में बैठकर अन्न से बने शरीर में टिका है। धीर पुरुष विशेष ज्ञान से उसे सब ओर देखते हैं — जो आनंद-रूप और अमृत होकर चमकता है।"',
    '4.8': '"उस ऊँचे और नीचे — दोनों रूपों वाले को देख लेने पर हृदय की गाँठ खुल जाती है, सारे संदेह कट जाते हैं, और मनुष्य के सारे कर्म क्षीण हो जाते हैं।"',
    '4.9': '"सोने जैसे सबसे ऊँचे कोश में निर्मल, बिना अंगों का ब्रह्म है। वह शुद्ध है, ज्योतियों की भी ज्योति है; आत्मा को जानने वाले उसी को जानते हैं।"',
    '4.10': _NA_TATRA,
    '4.11': '"यह अमृत ब्रह्म ही आगे है, ब्रह्म ही पीछे; ब्रह्म ही दाएँ और बाएँ; नीचे और ऊपर भी वही फैला है। यह सारा जगत यह सबसे श्रेष्ठ ब्रह्म ही है।"',

    # ── तीसरा मुण्डक, पहला खंड ──────────────────────────────────────────────
    '5.1': '"दो पक्षी, जो सदा साथ रहने वाले मित्र हैं, एक ही पेड़ पर बैठे हैं। उनमें से एक उस पेड़ का फल स्वाद लेकर खाता है; दूसरा बिना खाए बस देखता रहता है।"',
    '5.2': '"उसी पेड़ पर बैठा जीव डूबा हुआ है, और अपनी बेबसी से मोह में पड़कर शोक करता है। पर जब वह उस दूसरे को — भक्तों के सेवित ईश्वर को — और उसकी महिमा को देखता है, तब शोक से छूट जाता है।"',
    '5.3': '"जब देखने वाला उस सोने जैसे वर्ण वाले, सबके कर्ता, ईश्वर, ब्रह्मा के भी कारण पुरुष को देख लेता है — तब वह विद्वान पुण्य और पाप दोनों को झाड़कर, निर्मल होकर, परम समता को पा लेता है।"',
    '5.4': '"यह प्राण (परमात्मा) ही है जो सब प्राणियों में चमक रहा है। इसे जानकर विद्वान बढ़-चढ़कर बातें करने वाला नहीं रहता। वह आत्मा में ही खेलता है, आत्मा में ही रमता है, और कर्म करता रहता है — वही ब्रह्म को जानने वालों में श्रेष्ठ है।"',
    '5.5': '"यह आत्मा सत्य से, तप से, ठीक ज्ञान से और सदा के ब्रह्मचर्य से मिलता है। शरीर के भीतर वह ज्योति-रूप और शुद्ध है; दोषों से छूटे हुए यति उसे देखते हैं।"',
    '5.6': '"सत्य की ही जीत होती है, झूठ की नहीं। सत्य से ही देवताओं का वह मार्ग बिछा है जिससे पूरी हुई कामनाओं वाले ऋषि वहाँ पहुँचते हैं, जहाँ सत्य का परम धाम है।"',
    '5.7': '"वह बड़ा है, दिव्य है, सोच से परे रूप वाला है; और सूक्ष्म से भी सूक्ष्म होकर चमकता है। वह दूर से भी दूर है, और यहीं पास में भी; देखने वालों के लिए वह यहीं, हृदय की गुफा में रखा है।"',
    '5.8': '"वह न आँख से पकड़ में आता है, न वाणी से, न दूसरी इंद्रियों से, न तप से, न कर्म से। जब ज्ञान की निर्मलता से मन शुद्ध हो जाता है, तब ध्यान करने वाला उस बिना अंगों वाले को देख लेता है।"',
    '5.9': '"यह सूक्ष्म आत्मा चित्त से ही जाना जाता है — उस शरीर में जहाँ प्राण पाँच रूपों में बैठा है। प्राणियों का सारा चित्त प्राणों से गुँथा हुआ है; उसके शुद्ध होने पर यह आत्मा प्रकट हो जाता है।"',
    '5.10': '"शुद्ध मन वाला मनुष्य जिस-जिस लोक को मन से चाहता है, और जिन-जिन भोगों की कामना करता है — वह उसी लोक और उन्हीं भोगों को जीत लेता है। इसलिए ऐश्वर्य चाहने वाले को आत्मा के जानने वाले का आदर करना चाहिए।"',

    # ── तीसरा मुण्डक, दूसरा खंड ─────────────────────────────────────────────
    '6.1': '"वह आत्मज्ञानी उस परम ब्रह्म-धाम को जानता है, जिसमें सारा जगत टिका है और जो शुद्ध होकर चमकता है। जो धीर पुरुष कामनाएँ छोड़कर ऐसे पुरुष की उपासना करते हैं, वे इस बीज — फिर जन्म लेने — को पार कर जाते हैं।"',
    '6.2': '"जो भोगों को बड़ा मानकर उनकी कामना करता है, वह उन कामनाओं के कारण जहाँ-तहाँ जन्म लेता है। पर जिसकी कामनाएँ पूरी हो गईं और जिसने आत्मा को पा लिया, उसकी सारी कामनाएँ यहीं विलीन हो जाती हैं।"',
    '6.3': '"यह आत्मा न प्रवचन से मिलता है, न बुद्धि से, न बहुत सुनने से। जिसे यह स्वयं चुन लेता है, उसी को मिलता है; उसके सामने यह आत्मा अपना स्वरूप खोल देता है।"',
    '6.4': '"यह आत्मा न बलहीन को मिलता है, न लापरवाही से, न बिना ठीक लक्षण के तप से। पर जो विद्वान इन उपायों से यत्न करता है, उसका आत्मा ब्रह्म-धाम में प्रवेश कर जाता है।"',
    '6.5': '"इसे पाकर ऋषि ज्ञान से तृप्त, आत्मा में टिके हुए, राग से रहित और शांत हो जाते हैं। वे धीर पुरुष सब जगह फैले हुए उसे सब ओर से पाकर, उसी में जुड़े हुए, सबमें समा जाते हैं।"',
    '6.6': '"जिन्होंने वेदांत के ज्ञान से उसका अर्थ पक्का कर लिया है, और संन्यास के योग से जिनका मन शुद्ध हो गया है — वे यति अंत समय में ब्रह्मलोक में परम अमृत होकर सब ओर से मुक्त हो जाते हैं।"',
    '6.7': '"पंद्रह कलाएँ अपने-अपने आधार में चली जाती हैं, और सब इंद्रियाँ अपने-अपने देवताओं में। कर्म और विज्ञानमय आत्मा — सब उस परम अविनाशी में एक हो जाते हैं।"',
    '6.8': '"जैसे बहती हुई नदियाँ अपना नाम और रूप छोड़कर समुद्र में लीन हो जाती हैं, वैसे ही विद्वान नाम और रूप से छूटकर परे से भी परे उस दिव्य पुरुष को पा लेता है।"',
    '6.9': '"जो उस परम ब्रह्म को जान लेता है, वह ब्रह्म ही हो जाता है। उसके कुल में ब्रह्म को न जानने वाला कोई नहीं होता। वह शोक को पार कर जाता है, पाप को पार कर जाता है; हृदय की गाँठों से छूटकर अमर हो जाता है।"',
    '6.10': '"यही बात इस ऋचा में कही गई है — जो कर्म करने वाले, वेद के जानने वाले और ब्रह्म में टिके हुए हैं; जो श्रद्धा के साथ स्वयं एकर्षि अग्नि में आहुति देते हैं; और जिन्होंने विधि से शिरोव्रत निभाया है — यह ब्रह्मविद्या उन्हीं को बतानी चाहिए।"',
    '6.11': 'यही वह सत्य है जो पुराने समय में ऋषि अंगिरा ने कहा था। जिसने व्रत नहीं निभाया, वह इसे नहीं पढ़ता। परम ऋषियों को नमस्कार! परम ऋषियों को नमस्कार!',
}
